    write(out/'manual_final_review.json',{'question_id':q,'variant_id':read(out/'design.json')['variant_id'],'reviewed_at_utc':now(),'expected_wrong_answer':read(out/'design.json')['expected_wrong_answer'],'exactly_two_complete_calls':True,'results':rr,'credible_two_hit_possibility':all(hits),'mechanism_limit':'No original controls exist and no new controls were run. Two preset hits do not prove causal gain or the exact prospective reasoning mechanism. Plane427 both narratives actually use an erroneous angle-sign/ray-order computation, not the initially hypothesized simple missing final subtraction. Frozen design remains unchanged.','approval_status':'Research primary only; parent must launch NEW independent second review.'})
    print(q,finals,all(hits))
